splash_code:
flow: Down
spacing: 6

if mod.state.app.count == 0 {
  View{
    width: Fill
    height: Fit
    align: Center
    padding: Inset{top: 28 bottom: 28}
    Label{
      text: "No tasks yet — type above and press Add"
      draw_text +: {
        text_style: theme.font_regular {font_size: 12}
        color: #x64748b
      }
    }
  }
}

let i = 0
while i < mod.state.app.count {
  let item_index = i
  let todo = mod.state.app.todos[item_index]
  if todo.done {
    View{
      width: Fill
      height: Fit
      flow: Right
      spacing: 8
      align: VCenter
      padding: Inset{left: 12 right: 12 top: 9 bottom: 9}
      show_bg: true
      new_batch: true
      draw_bg +: {
        color: #x14291e
        radius: 8.0
      }
      Button{
        text: "Done"
        padding: Inset{left: 8 right: 8 top: 4 bottom: 4}
        draw_bg +: { color: #x16a34a radius: 5.0 }
        draw_text +: { text_style: theme.font_regular {font_size: 10} color: #xffffff }
        on_click: ||{
          mod.state.app.todos[item_index].done = false
          mod.state.app.version = mod.state.app.version + 1
        }
      }
      Label{
        width: Fill
        text: todo.text
        draw_text +: {
          text_style: theme.font_regular {font_size: 12}
          color: #x6db885
        }
      }
      Button{
        text: "Remove"
        padding: Inset{left: 8 right: 8 top: 4 bottom: 4}
        draw_bg +: { color: #x374151 radius: 5.0 }
        draw_text +: { text_style: theme.font_regular {font_size: 10} color: #x9ca3af }
        on_click: ||{
          mod.state.app.todos.remove(item_index)
          mod.state.app.count = mod.state.app.count - 1
          mod.state.app.version = mod.state.app.version + 1
        }
      }
    }
  }
  else {
    View{
      width: Fill
      height: Fit
      flow: Right
      spacing: 8
      align: VCenter
      padding: Inset{left: 12 right: 12 top: 9 bottom: 9}
      show_bg: true
      new_batch: true
      draw_bg +: {
        color: #x1e2430
        radius: 8.0
      }
      Button{
        text: "Todo"
        padding: Inset{left: 8 right: 8 top: 4 bottom: 4}
        draw_bg +: { color: #x334155 radius: 5.0 }
        draw_text +: { text_style: theme.font_regular {font_size: 10} color: #x94a3b8 }
        on_click: ||{
          mod.state.app.todos[item_index].done = true
          mod.state.app.version = mod.state.app.version + 1
        }
      }
      Label{
        width: Fill
        text: todo.text
        draw_text +: {
          text_style: theme.font_regular {font_size: 12}
          color: #xe2e8f0
        }
      }
      Button{
        text: "Remove"
        padding: Inset{left: 8 right: 8 top: 4 bottom: 4}
        draw_bg +: { color: #x374151 radius: 5.0 }
        draw_text +: { text_style: theme.font_regular {font_size: 10} color: #x9ca3af }
        on_click: ||{
          mod.state.app.todos.remove(item_index)
          mod.state.app.count = mod.state.app.count - 1
          mod.state.app.version = mod.state.app.version + 1
        }
      }
    }
  }
  i = i + 1
}
